create table if not exists public.profession_suggestions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null check(char_length(btrim(name)) between 3 and 80),status text not null default 'pending' check(status in ('pending','approved','rejected')),created_at timestamptz not null default now());alter table public.profession_suggestions enable row level security;drop policy if exists "Suggest profession" on public.profession_suggestions;create policy "Suggest profession" on public.profession_suggestions for insert to authenticated with check(user_id=(select auth.uid()) and status='pending');drop policy if exists "Read own suggestions" on public.profession_suggestions;create policy "Read own suggestions" on public.profession_suggestions for select to authenticated using(user_id=(select auth.uid()));grant select,insert on public.profession_suggestions to authenticated;create unique index if not exists profession_suggestions_user_name on public.profession_suggestions(user_id,lower(btrim(name)));